function UP(e) {
  const t = Date.now() - e;
  const n = Math.floor(t / 60000);
  if (n < 1) {
    return "刚刚";
  }
  if (n < 60) {
    return `${n} 分钟前`;
  }
  const r = Math.floor(n / 60);
  if (r < 24) {
    return `${r} 小时前`;
  }
  const s = Math.floor(r / 24);
  if (s < 30) {
    return `${s} 天前`;
  }
  const o = new Date(e);
  return `${o.getFullYear()}-${String(o.getMonth() + 1).padStart(2, "0")}-${String(o.getDate()).padStart(2, "0")}`;
}
